def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    budget = my_status['budget']
    hp = my_status['hp']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0

    units = int(supply // WATER_REQ)
    if units < 0:
        units = 0

    prev_bids = []
    desperate_count = 0
    rich_pressure = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev:
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(bid)
            if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
                desperate_count += 1
            if opp.get('budget', 0) >= DAILY_SALARY * 4:
                rich_pressure += 1

    highest_prev = max(prev_bids) if prev_bids else 0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 2
    if no_water_days >= 2:
        urgency += 4
    elif no_water_days >= 1:
        urgency += 2

    scarcity = 0
    if units <= 1:
        scarcity = 3
    elif units == 2:
        scarcity = 2
    else:
        scarcity = 1

    pressure = scarcity + urgency
    if desperate_count > 0:
        pressure += 1
    if rich_pressure >= 2:
        pressure += 1

    if not alive_opponents:
        if pressure >= 5:
            bid = DAILY_SALARY * 0.7
        elif pressure >= 3:
            bid = DAILY_SALARY * 0.45
        else:
            bid = DAILY_SALARY * 0.2
        return min(budget, max(0, bid))

    if pressure >= 7:
        target = max(DAILY_SALARY * 0.92, highest_prev + 2)
    elif pressure >= 5:
        target = max(DAILY_SALARY * 0.72, avg_prev + 2, highest_prev + 1)
    elif pressure >= 3:
        if units >= 2:
            target = max(DAILY_SALARY * 0.42, avg_prev)
        else:
            target = max(DAILY_SALARY * 0.58, highest_prev + 1)
    else:
        if units >= 2:
            target = DAILY_SALARY * 0.28
        else:
            target = max(DAILY_SALARY * 0.4, avg_prev * 0.9)

    if day >= 8 and hp <= 4:
        target = max(target, DAILY_SALARY * 0.8)

    if budget < target:
        if hp <= 2 or no_water_days >= 2:
            return budget
        target = min(target, budget)

    if target < 0:
        target = 0
    if target > budget:
        target = budget
    return target

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_budget = float(my_status.get('budget', 0.0))
    my_hp = float(my_status.get('hp', 0.0))

    alive_opponents = []
    for opp_id, o in opponents_status.items():
        if o is not None and o.get('alive', False):
            alive_opponents.append((opp_id, o))

    # Default conservative strategy: bid enough to cover our requirement, but not max.
    # Scale with supply: when supply is tight, bid more.
    supply_ratio = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Tight supply => higher bid; abundant => lower bid.
    base_fraction = 0.62 - 0.20 * supply_ratio  # ~0.42..0.62
    base_fraction = max(0.35, min(0.65, base_fraction))

    # React to yesterday's opponent bids if present.
    high_prev_threshold = DAILY_SALARY * 0.85
    prev_bids = []
    for opp_id, o in alive_opponents:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    if prev_bids:
        highest_prev_bid = max(prev_bids)
        # If someone was willing to pay aggressively, contest but undercut.
        if highest_prev_bid >= high_prev_threshold:
            # If our hp is low, we must secure water.
            if my_hp <= 2.0:
                target = min(my_budget, DAILY_SALARY * 0.92)
            else:
                target = min(my_budget, highest_prev_bid - 1.0)
                # Ensure still meaningful contest.
                target = max(target, DAILY_SALARY * 0.55)
        else:
            # Otherwise, bid around base but slightly above their max to win cheaply.
            target = max(DAILY_SALARY * base_fraction, highest_prev_bid + 1.5)
            target = min(my_budget, target)
    else:
        # No usable trace: bid around base.
        target = min(my_budget, DAILY_SALARY * base_fraction)

    # Safety bounds: never bid negative; also avoid bidding more than daily salary.
    target = max(0.0, min(target, DAILY_SALARY))

    # If our hp is critical, increase bid.
    if my_hp <= 1.5:
        target = min(my_budget, DAILY_SALARY * 0.98)
    elif my_hp <= 3.0:
        target = min(my_budget, max(target, DAILY_SALARY * 0.70))

    # If budget is extremely low, bid whatever we can.
    if my_budget <= 1.0:
        return float(my_budget)

    return float(target)

